import { Injectable, Logger } from '@nestjs/common';
import { FileSystemDataStoreEntity } from './entites/fileSystemDataStore.entity';
import {
  IncrementDataDto,
  IncrementDataResponseDto,
  StoreDataDto,
  StoreDataResponseDto,
} from './dto/store.dto';
import { FindDataDto, FindDataResponseDto } from './dto/find.dto';
import { RedisDataStoreEntity } from './entites/redisDataStore.entity';
import { MongoDataStoreEntity } from './entites/mongoDataStoreEntity.entity';
import { documentType } from './entites/documentType';

@Injectable()
export class DatastoreService {
  public static fileSystemDataStoreEntity: FileSystemDataStoreEntity;
  public static redisDataStoreEntity: RedisDataStoreEntity;
  public static mongoDataStoreEntity: MongoDataStoreEntity;
  private logger = new Logger(DatastoreService.name);
  public static async init(
    entites: Array<
      FileSystemDataStoreEntity | RedisDataStoreEntity | MongoDataStoreEntity
    >,
  ) {
    await Promise.all(
      entites.map(async (entity) => {
        if (entity) {
          await entity.init();
          if (entity instanceof FileSystemDataStoreEntity) {
            DatastoreService.fileSystemDataStoreEntity = entity;
          }
          if (entity instanceof RedisDataStoreEntity) {
            DatastoreService.redisDataStoreEntity = entity;
          }
          if (entity instanceof MongoDataStoreEntity) {
            DatastoreService.mongoDataStoreEntity = entity;
          }
        }
      }),
    );
  }

  async store(storeDataDto: StoreDataDto): Promise<StoreDataResponseDto> {
    const { data, context } = storeDataDto;
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'FILESYSTEM'
    ) {
      return DatastoreService.fileSystemDataStoreEntity.store(data, context);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'REDIS'
    ) {
      this.logger.debug('Storing data in redis');
      return DatastoreService.redisDataStoreEntity.store(data, context);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      return DatastoreService.mongoDataStoreEntity.store(data, context);
    }
  }

  async increment(
    incrementDataDto: IncrementDataDto,
  ): Promise<IncrementDataResponseDto> {
    const { data, context } = incrementDataDto;
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      return DatastoreService.mongoDataStoreEntity.increment(data, context);
    } else {
      this.logger.error('No datastore configured');
      return new IncrementDataResponseDto('No datastore configured');
    }
  }

  async getById(
    findDataDto: FindDataDto & { id: string },
  ): Promise<FindDataResponseDto> {
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'FILESYSTEM'
    ) {
      const { id } = findDataDto;
      const data = await DatastoreService.fileSystemDataStoreEntity.getById(id);
      return new FindDataResponseDto({ data });
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'REDIS'
    ) {
      const { id } = findDataDto;
      this.logger.debug(`Getting results from redis for ${id}`);
      const data = await DatastoreService.redisDataStoreEntity.getById(id);
      return new FindDataResponseDto({ data });
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      const context =
        findDataDto?.documentTypes && findDataDto.documentTypes.length > 0
          ? { documentTypes: findDataDto.documentTypes }
          : { documentType: findDataDto.documentType };
      const data = await DatastoreService.mongoDataStoreEntity.getById(
        findDataDto.id,
        context,
      );
      return new FindDataResponseDto({ data });
    }
  }
  async getByField({
    fieldKey,
    fieldValue,
    documentType,
    documentTypes,
    pagination,
  }: {
    fieldKey: string;
    fieldValue: string | Record<string, any>;
    documentType?: documentType;
    documentTypes?: documentType[];
    pagination?: { page: number; pageSize: number };
  }): Promise<FindDataResponseDto> {
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'FILESYSTEM'
    ) {
      const data = await DatastoreService.fileSystemDataStoreEntity.getByField(
        fieldKey,
        fieldValue,
        { documentType },
      );
      return new FindDataResponseDto({ data });
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'REDIS'
    ) {
      this.logger.debug(`Getting results from redis for ${fieldKey}`);
      const data = await DatastoreService.redisDataStoreEntity.getByField(
        fieldKey,
        fieldValue,
        {
          documentType,
        },
      );
      return new FindDataResponseDto({ data });
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      const context =
        documentTypes && documentTypes.length > 0
          ? { documentTypes: documentTypes }
          : { documentType };
      const data = await DatastoreService.mongoDataStoreEntity.getByField(
        fieldKey,
        fieldValue,
        context,
        pagination,
      );
      return new FindDataResponseDto({ data });
    }
  }
  async getByPattern({
    pattern,
    documentType,
    documentTypes,
  }: {
    pattern: string;
    documentType?: documentType;
    documentTypes?: documentType[];
  }) {
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'FILESYSTEM'
    ) {
      return DatastoreService.fileSystemDataStoreEntity.getByPattern(pattern);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'REDIS'
    ) {
      this.logger.debug(`Getting results from redis for ${pattern}`);
      return DatastoreService.redisDataStoreEntity.getByPattern(pattern);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      const context =
        documentTypes && documentTypes.length > 0
          ? { documentTypes: documentTypes }
          : { documentType };
      return DatastoreService.mongoDataStoreEntity.getByPattern(
        pattern,
        context,
      );
    }
  }

  async remove({
    id,
    documentType,
    documentTypes,
  }: {
    id: string;
    documentType?: documentType;
    documentTypes?: documentType[];
  }) {
    if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'FILESYSTEM'
    ) {
      return DatastoreService.fileSystemDataStoreEntity.remove(id);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'REDIS'
    ) {
      this.logger.debug(`Removing results from redis for ${id}`);
      return DatastoreService.redisDataStoreEntity.remove(id);
    } else if (
      process.env.DATASTORE &&
      process.env.DATASTORE.toUpperCase() === 'MONGO'
    ) {
      const context =
        documentTypes && documentTypes.length > 0
          ? { documentTypes: documentTypes }
          : { documentType };
      return DatastoreService.mongoDataStoreEntity.remove(id, context);
    }
  }
  async migrateDb() {
    return DatastoreService.mongoDataStoreEntity.migrate(
      'APOLLO_EXPORTED_DATA_INDEX',
      'APOLLO_EXPORTED_DATA_INDEX',
    );
  }

  async getPageCount({
    collection,
    fieldKey,
    fieldValue,
  }: {
    collection: string;
    fieldKey: string;
    fieldValue: any;
  }) {
    return DatastoreService.mongoDataStoreEntity.getPageCount({
      collection,
      fieldKey,
      fieldValue,
    });
  }
}

