import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { documentType } from '../../datastore/entites/documentType';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import { Persona } from './Persona';

@Injectable()
export class PersonaEntity {
  private readonly logger = new Logger(PersonaEntity.name);
  constructor(private readonly datastoreService: DatastoreService) {}

  async create(persona: Persona): Promise<Persona> {
    let createdAt = new Date().toISOString();
    if (persona?.id) {
      try {
        const existingPersona = await this.read(persona.id);
        createdAt = existingPersona.createdAt
          ? existingPersona.createdAt
          : new Date().toISOString();
      } catch (error) {
        this.logger.error(error);
        createdAt = new Date().toISOString();
      }
    }
    const entity = new Persona(persona);
    entity.createdAt = createdAt;
    entity.updatedAt = new Date().toISOString();
    const storeData: StoreDataDto = {
      data: entity,
      context: {
        uniqueId: entity.id,
        documentType: documentType.PERSONA,
      },
    };
    await this.datastoreService.store(storeData);
    return entity;
