          const collection = this.documentTypeToCollection(dt).collectionName;
          this.logger.debug(`Getting data from collection ${collection}`);
          const documents = await this.db
            .collection(collection)
            .find({
              id: { $regex: pattern },
            })
            .toArray();
          return documents.map((doc) => ({
            ...doc.data,
            _collection: collection,
          }));
        }),
      );

      const allDocuments = results.flat();
      if (allDocuments.length > 0) {
        return allDocuments;
      }
    } else {
      // Original single collection logic
      const collection =
        this.documentTypeToCollection(documentType).collectionName;
      this.logger.debug(`Getting data from collection ${collection}`);
      const documents = await this.db
        .collection(collection)
        .find({
          id: { $regex: pattern },
        })
        .toArray();

      if (documents && documents.length > 0) {
        return documents.map((doc) => doc.data);
      }
    }

    return [];
  }
  async getByField(
    fieldKey: string,
    fieldValue: any,
    context: datastoreContext & { documentTypes?: documentType[] },
    pagination?: { page: number; pageSize: number },
  ): Promise<Record<any, any>[]> {
    const { documentType, documentTypes } = context;

    // If documentTypes array is provided, search across multiple collections
    const collectionsToSearch = documentTypes
      ? documentTypes.map(
          (dt) => this.documentTypeToCollection(dt).collectionName,
        )
      : [this.documentTypeToCollection(documentType).collectionName];

    this.logger.debug(
      `Searching collections ${collectionsToSearch.join(', ')} for field ${fieldKey}`,
    );
    // Execute parallel queries across all collections

    const results = await Promise.all(
      collectionsToSearch.map(async (collection) => {
        let documents;
        if (pagination) {
          documents = await this.db
            .collection(collection)
            .find({
              [fieldKey]: fieldValue,
            })
            .skip(pagination.page * pagination.pageSize)
            .limit(pagination.pageSize)
            .toArray();
        } else {
          documents = await this.db
            .collection(collection)
            .find({
              [fieldKey]: fieldValue,
            })
            .toArray();
        }
        return documents.map((doc) => ({
          ...doc.data,
          _collection: collection, // Optional: Include source collection
        }));
      }),
    );

    // Flatten results from all collections
    const allDocuments = results.flat();

    this.logger.log(
      `Found ${allDocuments.length} documents across ${collectionsToSearch.length} collections`,
    );

    return allDocuments.length > 0 ? allDocuments : undefined;
  }

  async getByFieldAndAggregate(
    fieldKey: string,
    fieldValue: any,
    context: datastoreContext & { documentTypes?: documentType[] },
    customAggregation: Array<any>,
    pagination?: { page: number; pageSize: number },
  ) {
    const { documentType, documentTypes } = context;

    // Determine which collection(s) to search
    const collectionsToSearch = documentTypes
      ? documentTypes.map(
          (dt) => this.documentTypeToCollection(dt).collectionName,
        )
      : [this.documentTypeToCollection(documentType).collectionName];

    this.logger.debug(
      `getByFieldAndAggregate: Searching collections ${collectionsToSearch.join(', ')} for ${fieldKey}=${fieldValue}.`,
    );

    // Build a base pipeline that includes matching on the given fieldKey/fieldValue
    // then spread in any custom aggregation stages the caller provided.
    const buildPipeline = (scopedPagination?: {
      page: number;
      pageSize: number;
    }) => {
      const pipeline = [
        { $match: { [fieldKey]: fieldValue } },
        ...customAggregation,
      ];

      // If pagination is requested, apply skip/limit at the end
      if (scopedPagination) {
        pipeline.push({
          $skip: scopedPagination.page * scopedPagination.pageSize,
        });
        pipeline.push({ $limit: scopedPagination.pageSize });
      }

      return pipeline;
    };

    // For each collection, run the aggregation pipeline
    const resultsPerCollection = await Promise.all(
      collectionsToSearch.map(async (collection) => {
        this.logger.debug(`Running aggregation on collection: ${collection}`);

        const pipelineResult = await this.db
          .collection(collection)
          .aggregate(buildPipeline(pagination))
          .toArray();

        // Optionally annotate results with the source collection
        return pipelineResult.map((doc) => ({
          ...doc,
          _collection: collection,
        }));
      }),
    );

    // Flatten all results and return
    const allResults = resultsPerCollection.flat();
    return allResults;
  }

  async migrate(SOURCE_COLLECTION, TARGET_COLLECTION) {
    try {
      const sourceCollection = this.db.collection(SOURCE_COLLECTION);
      const targetCollection = this.db.collection(TARGET_COLLECTION);

      // Process documents in the source collection
      const cursor = sourceCollection.find();
      const BATCH_SIZE = 1000;
      let batch = [];
      let processedCount = 0;

      while (await cursor.hasNext()) {
        const doc = await cursor.next();

        // Transform campaignIds to the new format
        if (doc.data && doc.data.campaignIds) {
          const newDocument = {
            ...doc,
            data: {
              ...doc.data,
              campaignIds: Object.entries(doc.data.campaignIds).map(
                ([id, value]) => ({
                  id,
                  // eslint-disable-next-line
                  // @ts-ignore
                  ...value,
                }),
              ),
            },
          };

          // Remove the _id field to avoid duplicate key errors in the new collection
          delete newDocument._id;
          batch.push(newDocument);

          // Insert batch when full
          if (batch.length === BATCH_SIZE) {
            await targetCollection.insertMany(batch);
            processedCount += batch.length;
            this.logger.log(`Inserted ${processedCount} documents so far`);
            batch = [];
          }
        } else {
          this.logger.log(
            `Skipping document with missing data or campaignIds field: ${doc._id}`,
          );
        }
      }

      // Insert remaining documents
      if (batch.length > 0) {
        await targetCollection.insertMany(batch);
        processedCount += batch.length;
      }

      this.logger.log(
        `Transformation completed. Inserted ${processedCount} documents into ${TARGET_COLLECTION}.`,
      );
    } catch (error) {
      this.logger.error('An error occurred:', error);
    }
  }

  async getPageCount({
    collection,
    fieldKey,
    fieldValue,
  }: {
    collection: string;
    fieldKey: string;
    fieldValue: any;
  }) {
    const count = await this.db
      .collection(collection)
      .countDocuments({ [fieldKey]: fieldValue });
    return count;
  }
}

