/**
 * Smartlead exposes a numeric `warmup_reputation` for every inbox (mailbox) it
 * warms up. We keep that raw number on the email account as the
 * `deliverabilityScore` and expose the human readable band separately so that
 * the internal portal can group inboxes without duplicating the mapping rules.
 *
 * The bands are:
 *  - 100      -> High
 *  - 98 - 99  -> Medium
 *  - 95 - 97  -> Low
 *  - < 95     -> Burned
 *  - missing  -> Unknown
 */
export enum DeliverabilityScore {
  HIGH = 'High',
  MEDIUM = 'Medium',
  LOW = 'Low',
  BURNED = 'Burned',
  UNKNOWN = 'Unknown',
}

/**
 * Alias kept for readability at call sites which talk about "bands" rather than
 * "scores". Both point at the same enum values.
 */
export const DeliverabilityBand = DeliverabilityScore;
export type DeliverabilityBand = DeliverabilityScore;

export const HIGH_DELIVERABILITY_SCORE = 100;
export const MEDIUM_DELIVERABILITY_SCORE = 98;
export const LOW_DELIVERABILITY_SCORE = 95;

/**
 * Smartlead is not consistent with the type of the warm up reputation, it can
 * come back as a number (`100`), a numeric string (`"100"`) or a percentage
 * string (`"100%"`). This normalizes all of those into a number, returning
 * `undefined` when the value is missing or unparsable.
 */
export function parseDeliverabilityScore(
  score?: number | string | null,
): number | undefined {
  if (score === null || score === undefined || score === '') {
    return undefined;
  }
  if (typeof score === 'number') {
    return Number.isFinite(score) ? score : undefined;
  }
  const parsed = parseFloat(`${score}`.replace('%', '').trim());
  return Number.isFinite(parsed) ? parsed : undefined;
}

/**
 * Maps the numeric warm up reputation onto its deliverability band.
 */
export function mapDeliverabilityScore(
  score?: number | string | null,
): DeliverabilityScore {
  const numericScore = parseDeliverabilityScore(score);
  if (numericScore === undefined) {
    return DeliverabilityScore.UNKNOWN;
  }
  if (numericScore >= HIGH_DELIVERABILITY_SCORE) {
    return DeliverabilityScore.HIGH;
  }
  if (numericScore >= MEDIUM_DELIVERABILITY_SCORE) {
    return DeliverabilityScore.MEDIUM;
  }
  if (numericScore >= LOW_DELIVERABILITY_SCORE) {
    return DeliverabilityScore.LOW;
  }
  return DeliverabilityScore.BURNED;
}

import {
  DeliverabilityScore,
  mapDeliverabilityScore,
  parseDeliverabilityScore,
} from '../dto/deliverabilityScore.dto';

/**
 * A warmed up Smartlead inbox (mailbox) which can be assigned to campaigns.
 *
 * The account is keyed by the Smartlead inbox id, it holds on to the Smartlead
 * client (the tenant the inbox belongs to inside of Smartlead), the sending
 * email address and derives the sending domain from that email address.
 *
 * `deliverabilityScore` is the raw Smartlead warm up reputation, the mapped
 * band is exposed separately via `deliverabilityBand`.
 */
export class EmailAccount {
  /** Smartlead inbox id, this is the unique key of the account. */
  smartleadInboxId: string;
  /** The sending email address of the inbox. */
  email: string;
  /** The Smartlead client (tenant) which owns the inbox. */
  smartleadClientId: string;
  /** Sending domain, derived from the email address. */
  domain: string;
  /** Free form tags used by delivery ops to group inboxes. */
  tags: string[];
  /** Campaigns the inbox has been associated with. */
  campaignIds: string[];
  /** Raw Smartlead warm up reputation. */
  deliverabilityScore?: number;
  /** Creation time of the inbox inside of Smartlead. */
  createdAt?: string;

  constructor(
    partial: Partial<EmailAccount> & {
      smartleadInboxId?: string | number;
      smartleadClientId?: string | number;
      deliverabilityScore?: number | string;
    } = {},
  ) {
    Object.assign(this, partial);
    this.smartleadInboxId = EmailAccount.normalizeId(partial?.smartleadInboxId);
    this.smartleadClientId = EmailAccount.normalizeId(
      partial?.smartleadClientId,
    );
    this.email = partial?.email ? `${partial.email}`.trim() : partial?.email;
    this.domain = partial?.domain
      ? partial.domain
      : EmailAccount.deriveDomain(this.email);
    this.tags = EmailAccount.normalizeStringList(partial?.tags);
    this.campaignIds = EmailAccount.normalizeStringList(partial?.campaignIds);
    const deliverabilityScore = parseDeliverabilityScore(
      partial?.deliverabilityScore,
    );
    if (deliverabilityScore === undefined) {
      delete this.deliverabilityScore;
    } else {
      this.deliverabilityScore = deliverabilityScore;
    }
    if (!partial?.createdAt) {
      delete this.createdAt;
    }
  }

  /** Number of campaigns the inbox is currently associated with. */
  get numberOfCampaignAssociated(): number {
    return this.campaignIds?.length ? this.campaignIds.length : 0;
  }

  /** Alias of {@link numberOfCampaignAssociated}. */
  get numberOfCampaignsAssociated(): number {
    return this.numberOfCampaignAssociated;
  }

  /** The deliverability score mapped onto its band. */
  get deliverabilityBand(): DeliverabilityScore {
    return mapDeliverabilityScore(this.deliverabilityScore);
  }

  /** Alias of {@link deliverabilityBand}. */
  get deliverabilityScoreBand(): DeliverabilityScore {
    return this.deliverabilityBand;
  }

  /** Alias of {@link deliverabilityBand}. */
  get deliverabilityRating(): DeliverabilityScore {
    return this.deliverabilityBand;
  }

  /** The deliverability score mapped onto its band. */
  getDeliverabilityBand(): DeliverabilityScore {
    return this.deliverabilityBand;
  }

  /**
   * Associates the inbox with a campaign. The operation is idempotent, a
   * campaign which is already associated is not added twice.
   *
   * @returns true when the account changed, false when it was already
   * associated with the campaign.
   */
  associateCampaign(campaignId: string): boolean {
    if (!campaignId) {
      return false;
    }
    if (!Array.isArray(this.campaignIds)) {
      this.campaignIds = [];
    }
    if (this.campaignIds.includes(campaignId)) {
      return false;
    }
    this.campaignIds.push(campaignId);
    return true;
  }

  /** Whether the inbox is already associated with the given campaign. */
  hasCampaign(campaignId: string): boolean {
    return Boolean(this.campaignIds?.includes(campaignId));
  }

  /**
   * Maps a raw datastore document (or an already unwrapped document) onto an
   * {@link EmailAccount}.
   */
  static map(item: any): EmailAccount {
    if (item instanceof EmailAccount) {
      return item;
    }
    if (item?.data) {
      return new EmailAccount(item.data);
    }
    return new EmailAccount(item);
  }

  /** Alias of {@link EmailAccount.map}. */
  static mapEmailAccount(item: any): EmailAccount {
    return EmailAccount.map(item);
  }

  /**
   * Maps a Smartlead email account payload onto the fields we persist.
   * See https://server.smartlead.ai/api/v1/email-accounts/
   */
  static fromSmartleadInbox(
    inbox: any,
    overrides: Partial<EmailAccount> = {},
  ): EmailAccount {
    return new EmailAccount({
      smartleadInboxId: EmailAccount.normalizeId(inbox?.id),
      email: inbox?.from_email ? inbox.from_email : inbox?.email,
      smartleadClientId: EmailAccount.normalizeId(inbox?.client_id),
      createdAt: inbox?.created_at,
      deliverabilityScore: EmailAccount.readWarmupReputation(inbox),
      ...overrides,
    });
  }

  /**
   * Reads the warm up reputation out of a Smartlead email account payload.
   */
  static readWarmupReputation(inbox: any): number | undefined {
    return parseDeliverabilityScore(
      inbox?.warmup_details?.warmup_reputation !== undefined
        ? inbox?.warmup_details?.warmup_reputation
        : inbox?.warmup_reputation,
    );
  }

  /** Maps a warm up reputation onto its deliverability band. */
  static mapDeliverabilityScore(
    score?: number | string | null,
  ): DeliverabilityScore {
    return mapDeliverabilityScore(score);
  }

  /** Derives the sending domain from an email address. */
  static deriveDomain(email?: string): string | undefined {
    if (!email || !`${email}`.includes('@')) {
      return undefined;
    }
    const domain = `${email}`.trim().split('@').pop();
    return domain ? domain : undefined;
  }

  private static normalizeId(id?: string | number): string {
    if (id === null || id === undefined || id === '') {
      return undefined;
    }
    return `${id}`;
  }

  private static normalizeStringList(values?: any): string[] {
    if (!values) {
      return [];
    }
    const list = Array.isArray(values) ? values : [values];
    return list
      .filter((value) => value !== null && value !== undefined && value !== '')
      .map((value) => `${value}`)
      .filter((value, index, all) => all.indexOf(value) === index);
  }
}

