import { EmailAccount } from './emailAccount.entity';

/**
 * A list of email accounts. Pagination metadata is attached as non enumerable
 * properties so the result can be treated either as a plain array of accounts
 * (`list.map(...)`) or as a paginated response (`list.pageCount`).
 */
export type EmailAccountList = EmailAccount[] & {
  emailAccounts: EmailAccount[];
  data: EmailAccount[];
  page?: number;
  pageSize?: number;
  pageCount?: number;
  total?: number;
};

export function toEmailAccountList(
  emailAccounts: EmailAccount[],
  metadata: {
    page?: number;
    pageSize?: number;
    pageCount?: number;
    total?: number;
  } = {},
): EmailAccountList {
  const list = [...emailAccounts] as EmailAccountList;
  const attach = (key: string, value: any) => {
    Object.defineProperty(list, key, {
      value,
      enumerable: false,
      writable: true,
      configurable: true,
    });
  };
  attach('emailAccounts', list);
  attach('data', list);
  Object.entries(metadata).forEach(([key, value]) => {
    if (value !== undefined) {
      attach(key, value);
    }
  });
  return list;
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { DatastoreService } from '../../datastore/datastore.service';
import { StoreDataDto } from '../../datastore/dto/store.dto';
import { documentType } from '../../datastore/entites/documentType';
import { EmailAccount } from './emailAccount.entity';

export const SMARTLEAD_API_BASE_URL = 'https://server.smartlead.ai/api/v1';
/** Smartlead caps the email account listing endpoint at 100 records. */
export const SMARTLEAD_INBOX_PAGE_SIZE = 100;
/** Safety net so a misbehaving remote never turns into an endless loop. */
const MAX_REMOTE_PAGES = 50;

/**
 * The email account datastore. It owns every read/write of the
 * `EMAIL_ACCOUNT` documents, which are keyed by the Smartlead inbox id, and the
 * calls made against the Smartlead email account (inbox) API.
 */
@Injectable()
export class EmailInfraEntity {
  private readonly logger = new Logger(EmailInfraEntity.name);
  constructor(private readonly datastoreService: DatastoreService) {}

  /** Creates or updates an email account. */
  async create(emailAccount: EmailAccount): Promise<EmailAccount> {
    const entity =
      emailAccount instanceof EmailAccount
        ? emailAccount
        : new EmailAccount(emailAccount);
    if (!entity.smartleadInboxId) {
      throw new NotFoundException('smartleadInboxId is required');
    }
    this.logger.log(
      `Storing email account for inbox: ${entity.smartleadInboxId}`,
    );
    await this.datastoreService.store(
      new StoreDataDto({
        data: { ...entity },
        context: {
          uniqueId: entity.smartleadInboxId,
          documentType: documentType.EMAIL_ACCOUNT,
        },
      }),
    );
    return entity;
  }

  /** Reads an email account by inbox id, throws when it does not exist. */
  async read(smartleadInboxId: string): Promise<EmailAccount> {
    const emailAccount = await this.find(smartleadInboxId);
    if (!emailAccount) {
      throw new NotFoundException(
        `Email account not found for inbox: ${smartleadInboxId}`,
      );
    }
    return emailAccount;
  }

  /** Reads an email account by inbox id, resolves undefined when missing. */
  async find(smartleadInboxId: string): Promise<EmailAccount | undefined> {
    if (!smartleadInboxId) {
      return undefined;
    }
    const [emailAccount] = await this.query(
      'data.smartleadInboxId',
      `${smartleadInboxId}`,
    );
    return emailAccount;
  }

  /** Reads an email account by email address, throws when it does not exist. */
  async readByEmail(email: string): Promise<EmailAccount> {
    const emailAccount = await this.findByEmail(email);
    if (!emailAccount) {
      throw new NotFoundException(`Email account not found for email: ${email}`);
    }
    return emailAccount;
  }

  /** Reads an email account by email address, undefined when missing. */
  async findByEmail(email: string): Promise<EmailAccount | undefined> {
    if (!email) {
      return undefined;
    }
    const [emailAccount] = await this.query('data.email', `${email}`.trim());
    return emailAccount;
  }

  /** Reads every email account belonging to a Smartlead client. */
  async readBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    if (!smartleadClientId) {
      return [];
    }
    return this.query(
      'data.smartleadClientId',
      `${smartleadClientId}`,
      pagination,
    );
  }

  /** Reads every email account, optionally a single page of them. */
  async readAll(pagination?: {
    page: number;
    pageSize: number;
  }): Promise<EmailAccount[]> {
    return this.query(
      'data.smartleadInboxId',
      { $exists: true },
      pagination,
    ) as Promise<EmailAccount[]>;
  }

  /** Total number of stored email accounts. */
  async count(): Promise<number> {
    try {
      if (typeof this.datastoreService?.getPageCount !== 'function') {
        return undefined;
      }
      const count = await this.datastoreService.getPageCount({
        collection: documentType.EMAIL_ACCOUNT,
        fieldKey: 'data.smartleadInboxId',
        fieldValue: { $exists: true },
      });
      return typeof count === 'number' ? count : undefined;
    } catch (error) {
      this.logger.warn(`Unable to count email accounts: ${error}`);
      return undefined;
    }
  }

  /** Removes an email account. */
  async delete(smartleadInboxId: string): Promise<{ message: string }> {
    this.logger.log(`Deleting email account for inbox: ${smartleadInboxId}`);
    await this.datastoreService.remove({
      id: smartleadInboxId,
      documentType: documentType.EMAIL_ACCOUNT,
    });
    return { message: 'Email account deleted successfully' };
  }

  private async query(
    fieldKey: string,
    fieldValue: string | Record<string, any>,
    pagination?: { page: number; pageSize: number },
  ): Promise<EmailAccount[]> {
    const res = await this.datastoreService.getByField({
      fieldKey,
      fieldValue,
      documentType: documentType.EMAIL_ACCOUNT,
      ...(pagination ? { pagination } : {}),
    });
    const documents = Array.isArray(res?.data)
      ? res.data
      : res?.data
        ? [res.data]
        : [];
    return documents
      .filter((document) => Boolean(document))
      .map((document) => EmailAccount.map(document))
      .filter((emailAccount) => Boolean(emailAccount?.smartleadInboxId));
  }

  /**
   * Fetches a single inbox from Smartlead, throws a not found error when the
   * remote inbox does not exist.
   */
  async fetchRemoteInbox(smartleadInboxId: string): Promise<any> {
    const inbox = await this.findRemoteInbox(smartleadInboxId);
    if (!inbox) {
      throw new NotFoundException(
        `Smartlead inbox not found: ${smartleadInboxId}`,
      );
    }
    return inbox;
  }

  /** Fetches a single inbox from Smartlead, undefined when it is unknown. */
  async findRemoteInbox(smartleadInboxId: string): Promise<any | undefined> {
    if (!smartleadInboxId) {
      return undefined;
    }
    const response = await this.requestSmartlead(
      `email-accounts/${smartleadInboxId}/`,
    );
    const inbox = EmailInfraEntity.matchInbox(response, smartleadInboxId);
    if (inbox) {
      return inbox;
    }
    // Older Smartlead accounts do not expose the single inbox endpoint, fall
    // back to the full inbox listing.
    const inboxes = await this.fetchRemoteInboxes();
    return EmailInfraEntity.matchInbox(inboxes, smartleadInboxId);
  }

  /**
   * Fetches every inbox from Smartlead, optionally narrowed down to a single
   * Smartlead client.
   * GET https://server.smartlead.ai/api/v1/email-accounts/
   */
  async fetchRemoteInboxes({
    smartleadClientId,
  }: { smartleadClientId?: string } = {}): Promise<any[]> {
    const inboxes: any[] = [];
    const seen = new Set<string>();
    for (let page = 0; page < MAX_REMOTE_PAGES; page++) {
      const offset = page * SMARTLEAD_INBOX_PAGE_SIZE;
      const response = await this.requestSmartlead(
        `email-accounts/?offset=${offset}&limit=${SMARTLEAD_INBOX_PAGE_SIZE}`,
      );
      const batch = EmailInfraEntity.toInboxArray(response);
      if (!batch.length) {
        break;
      }
      const newInboxes = batch.filter(
        (inbox) => inbox?.id !== undefined && !seen.has(`${inbox.id}`),
      );
      newInboxes.forEach((inbox) => {
        seen.add(`${inbox.id}`);
        inboxes.push(inbox);
      });
      if (!newInboxes.length || batch.length < SMARTLEAD_INBOX_PAGE_SIZE) {
        break;
      }
    }
    this.logger.log(`Fetched ${inboxes.length} inboxes from Smartlead`);
    if (!smartleadClientId) {
      return inboxes;
    }
    return inboxes.filter(
      (inbox) => `${inbox?.client_id}` === `${smartleadClientId}`,
    );
  }

  private async requestSmartlead(path: string): Promise<any | undefined> {
    const apiKey = process.env.SMARTLEAD_REPORT_API_KEY;
    const separator = path.includes('?') ? '&' : '?';
    const url = `${SMARTLEAD_API_BASE_URL}/${path}${separator}api_key=${apiKey}`;
    try {
      const res = await fetch(url);
      const failed =
        res?.ok === false ||
        (typeof res?.status === 'number' && res.status >= 400);
      if (failed) {
        this.logger.warn(`Smartlead request failed (${res?.status}): ${path}`);
        return undefined;
      }
      return await res.json();
    } catch (error) {
      this.logger.error(`Error calling Smartlead for ${path}: ${error}`);
      return undefined;
    }
  }

  /** Normalizes the different shapes the Smartlead API responds with. */
  static toInboxArray(response: any): any[] {
    if (!response) {
      return [];
    }
    if (Array.isArray(response)) {
      return response.filter(Boolean);
    }
    if (Array.isArray(response?.data)) {
      return response.data.filter(Boolean);
    }
    if (Array.isArray(response?.email_accounts)) {
      return response.email_accounts.filter(Boolean);
    }
    if (response?.id !== undefined) {
      return [response];
    }
    return [];
  }

  private static matchInbox(response: any, smartleadInboxId: string): any {
    return EmailInfraEntity.toInboxArray(response).find(
      (inbox) => `${inbox?.id}` === `${smartleadInboxId}`,
    );
  }
}

