import {
  BadRequestException,
  Injectable,
  Logger,
  NotFoundException,
  Optional,
} from '@nestjs/common';
import { DatastoreService } from '../datastore/datastore.service';
import {
  AssociateEmailAccountsInput,
  EmailAccountInput,
  EmailAccountListInput,
  EmailAccountReference,
} from './dto/emailAccount.dto';
import { EmailAccount } from './entities/emailAccount.entity';
import {
  EmailAccountList,
  toEmailAccountList,
} from './entities/emailAccountList';
import { EmailInfraEntity } from './entities/emailinfra.entity';

/** Campaigns run for 10 days unless we are told otherwise. */
export const DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN = 10;
/** Every warmed up inbox sends 20 emails a day. */
export const DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY = 20;
/** Default page size of the email account listing. */
export const DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE = 100;

@Injectable()
export class EmailinfraService {
  private readonly logger = new Logger(EmailinfraService.name);
  private readonly emailInfraEntity: EmailInfraEntity;
  constructor(
    @Optional() private readonly datastoreService?: DatastoreService,
    @Optional() emailInfraEntity?: EmailInfraEntity,
  ) {
    this.emailInfraEntity = emailInfraEntity
      ? emailInfraEntity
      : new EmailInfraEntity(this.datastoreService);
  }

  /**
   * Works out how many inboxes a campaign needs.
   *
   * Example: 500 emails to send, over 10 days, at 20 emails per inbox per day
   * means we need 500 / 10 / 20 = 2.5 -> 2 inboxes.
   */
  getRequiredNumberOfInboxes({
    totalNumberOfEmailsToSend,
    numberOfDaysInCampaign,
    numberOfEmailsPerInboxPerDay,
  }: {
    totalNumberOfEmailsToSend?: number;
    numberOfDaysInCampaign?: number;
    numberOfEmailsPerInboxPerDay?: number;
  }): number {
    const totalEmails = Number(totalNumberOfEmailsToSend);
    const days =
      Number(numberOfDaysInCampaign) > 0
        ? Number(numberOfDaysInCampaign)
        : DEFAULT_NUMBER_OF_DAYS_IN_CAMPAIGN;
    const emailsPerInboxPerDay =
      Number(numberOfEmailsPerInboxPerDay) > 0
        ? Number(numberOfEmailsPerInboxPerDay)
        : DEFAULT_NUMBER_OF_EMAILS_PER_INBOX_PER_DAY;
    if (!Number.isFinite(totalEmails) || totalEmails <= 0) {
      return 0;
    }
    return Math.floor(totalEmails / days / emailsPerInboxPerDay);
  }

  /**
   * Returns the best inboxes of a Smartlead client for a campaign.
   *
   * The size of the pool is derived from the campaign volume, the inboxes are
   * then ranked by:
   *  1. deliverability score, highest first
   *  2. number of associated campaigns, lowest first
   *  3. number of other inboxes on the same domain, lowest first
   *  4. creation time, oldest first
   *
   * See: https://app.clickup.com/18036112/v/dc/h6dcg-8771/h6dcg-44571
   */
  async getBestEmailAccountsForCampaign({
    smartleadClientId,
    campaignId,
    numberOfDaysInCampaign,
    totalNumberOfEmailsToSend,
    numberOfEmailsPerInboxPerDay,
  }: EmailAccountListInput): Promise<EmailAccountList> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const requiredNumberOfInboxes = this.getRequiredNumberOfInboxes({
      totalNumberOfEmailsToSend,
      numberOfDaysInCampaign,
      numberOfEmailsPerInboxPerDay,
    });
    this.logger.log(
      `Campaign ${campaignId} requires ${requiredNumberOfInboxes} inboxes for ${totalNumberOfEmailsToSend} emails`,
    );
    const emailAccounts =
      await this.emailInfraEntity.readBySmartleadClientId(smartleadClientId);
    const rankedEmailAccounts = EmailinfraService.rankEmailAccounts(
      emailAccounts ? emailAccounts : [],
    );
    if (rankedEmailAccounts.length < requiredNumberOfInboxes) {
      this.logger.warn(
        `Only ${rankedEmailAccounts.length} inboxes available for client ${smartleadClientId}, ${requiredNumberOfInboxes} were required`,
      );
    }
    return toEmailAccountList(
      rankedEmailAccounts.slice(0, requiredNumberOfInboxes),
      {
        campaignId,
        smartleadClientId,
        requiredNumberOfInboxes,
        totalNumberOfEmailsToSend,
      },
    );
  }

  /**
   * Ranks inboxes by deliverability score (descending), number of associated
   * campaigns (ascending), number of other inboxes sharing the same domain
   * (ascending) and creation time (oldest first).
   */
  static rankEmailAccounts(emailAccounts: EmailAccount[]): EmailAccount[] {
    const accounts = (emailAccounts ? emailAccounts : []).map((emailAccount) =>
      EmailAccount.map(emailAccount),
    );
    const inboxesPerDomain = accounts.reduce<Record<string, number>>(
      (acc, emailAccount) => {
        const domain = EmailinfraService.domainKey(emailAccount);
        acc[domain] = (acc[domain] ? acc[domain] : 0) + 1;
        return acc;
      },
      {},
    );
    const otherInboxesOnDomain = (emailAccount: EmailAccount) => {
      const domain = EmailinfraService.domainKey(emailAccount);
      const total = inboxesPerDomain[domain] ? inboxesPerDomain[domain] : 1;
      return total - 1;
    };
    const score = (emailAccount: EmailAccount) =>
      typeof emailAccount?.deliverabilityScore === 'number'
        ? emailAccount.deliverabilityScore
        : -1;
    const createdAt = (emailAccount: EmailAccount) => {
      const time = new Date(emailAccount?.createdAt).getTime();
      return Number.isFinite(time) ? time : Number.MAX_SAFE_INTEGER;
    };
    return accounts.sort((a, b) => {
      const byScore = score(b) - score(a);
      if (byScore !== 0) {
        return byScore;
      }
      const byCampaigns =
        a.numberOfCampaignAssociated - b.numberOfCampaignAssociated;
      if (byCampaigns !== 0) {
        return byCampaigns;
      }
      const byDomain = otherInboxesOnDomain(a) - otherInboxesOnDomain(b);
      if (byDomain !== 0) {
        return byDomain;
      }
      const byCreatedAt = createdAt(a) - createdAt(b);
      if (byCreatedAt !== 0) {
        return byCreatedAt;
      }
      return `${a?.smartleadInboxId}`.localeCompare(`${b?.smartleadInboxId}`);
    });
  }

  private static domainKey(emailAccount: EmailAccount): string {
    const domain = emailAccount?.domain
      ? emailAccount.domain
      : EmailAccount.deriveDomain(emailAccount?.email);
    return domain ? `${domain}`.toLowerCase() : '';
  }

  /**
   * Associates inboxes with a campaign.
   *
   * Duplicated inbox ids in the request are treated as a single inbox and the
   * association is idempotent. When any of the requested inboxes is unknown the
   * whole request is rejected, nothing is written.
   */
  async associateEmailAccountsWithCampaign({
    emailAccountIds,
    campaignId,
  }: AssociateEmailAccountsInput): Promise<EmailAccountList> {
    if (!campaignId) {
      throw new BadRequestException('campaignId is required');
    }
    const uniqueEmailAccountIds = (
      Array.isArray(emailAccountIds)
        ? emailAccountIds
        : emailAccountIds
          ? [emailAccountIds]
          : []
    )
      .filter((id) => id !== null && id !== undefined && id !== '')
      .map((id) => `${id}`)
      .filter((id, index, all) => all.indexOf(id) === index);
    if (!uniqueEmailAccountIds.length) {
      throw new BadRequestException('emailAccountIds is required');
    }
    this.logger.log(
      `Associating ${uniqueEmailAccountIds.length} inboxes with campaign ${campaignId}`,
    );
    // Read everything up front so a single missing inbox rejects the whole
    // request without writing anything.
    const emailAccounts = await Promise.all(
      uniqueEmailAccountIds.map((id) => this.emailInfraEntity.find(id)),
    );
    const missingEmailAccountIds = uniqueEmailAccountIds.filter(
      (id, index) => !emailAccounts[index],
    );
    if (missingEmailAccountIds.length) {
      this.logger.error(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
      throw new NotFoundException(
        `Email accounts not found: ${missingEmailAccountIds.join(', ')}`,
      );
    }
    const associatedEmailAccounts: EmailAccount[] = [];
    for (const emailAccount of emailAccounts) {
      if (emailAccount.associateCampaign(campaignId)) {
        await this.emailInfraEntity.create(emailAccount);
      } else {
        this.logger.log(
          `Inbox ${emailAccount.smartleadInboxId} is already associated with campaign ${campaignId}`,
        );
      }
      associatedEmailAccounts.push(emailAccount);
    }
    return toEmailAccountList(associatedEmailAccounts, {
      message: 'Email accounts associated successfully',
      campaignId,
      emailAccountIds: uniqueEmailAccountIds,
    });
  }

  /**
   * Creates (or refreshes) an email account. The creation time and the warm up
   * reputation are always hydrated from Smartlead, an inbox which does not
   * exist in Smartlead is rejected with a not found error.
   */
  async saveEmailAccount(
    emailAccount: EmailAccountInput,
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailinfraService.readInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    this.logger.log(`Saving email account for inbox: ${smartleadInboxId}`);
    const inbox = await this.emailInfraEntity.fetchRemoteInbox(
      smartleadInboxId,
    );
    return this.saveFromRemoteInbox(inbox, {
      ...emailAccount,
      smartleadInboxId,
    });
  }

  /** Reads an email account by inbox id (or by payload). */
  async getEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailinfraService.readInboxId(emailAccount);
    if (smartleadInboxId) {
      return this.emailInfraEntity.read(smartleadInboxId);
    }
    const email =
      typeof emailAccount === 'object' && emailAccount?.email
        ? emailAccount.email
        : undefined;
    if (email) {
      return this.emailInfraEntity.readByEmail(email);
    }
    throw new BadRequestException('smartleadInboxId or email is required');
  }

  /** Reads an email account by inbox id. */
  async getEmailAccountById(smartleadInboxId: string): Promise<EmailAccount> {
    return this.emailInfraEntity.read(smartleadInboxId);
  }

  /** Reads an email account by inbox id. */
  async getEmailAccountBySmartleadInboxId(
    smartleadInboxId: string,
  ): Promise<EmailAccount> {
    return this.emailInfraEntity.read(smartleadInboxId);
  }

  /** Reads a page of email accounts. */
  async getAllEmailAccounts(
    pagination?: { page?: number; pageSize?: number } | number,
    maybePageSize?: number,
  ): Promise<EmailAccountList> {
    const { page, pageSize } = EmailinfraService.readPagination(
      pagination,
      maybePageSize,
    );
    this.logger.log(`Getting email accounts page ${page} of size ${pageSize}`);
    const [emailAccounts, total] = await Promise.all([
      this.emailInfraEntity.readAll({ page, pageSize }),
      this.emailInfraEntity.count(),
    ]);
    return toEmailAccountList(emailAccounts ? emailAccounts : [], {
      page,
      pageSize,
      total,
      pageCount:
        typeof total === 'number' ? Math.ceil(total / pageSize) : undefined,
    });
  }

  /** Reads an email account by its email address. */
  async getEmailAccountByEmail(email: string): Promise<EmailAccount> {
    return this.emailInfraEntity.readByEmail(email);
  }

  /** Reads every email account of a Smartlead client. */
  async getEmailAccountBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page?: number; pageSize?: number },
  ): Promise<EmailAccountList> {
    if (!smartleadClientId) {
      throw new BadRequestException('smartleadClientId is required');
    }
    const emailAccounts = await this.emailInfraEntity.readBySmartleadClientId(
      smartleadClientId,
      pagination
        ? EmailinfraService.readPagination(pagination)
        : undefined,
    );
    return toEmailAccountList(emailAccounts ? emailAccounts : [], {
      smartleadClientId,
    });
  }

  /** Alias of {@link getEmailAccountBySmartleadClientId}. */
  async getEmailAccountsBySmartleadClientId(
    smartleadClientId: string,
    pagination?: { page?: number; pageSize?: number },
  ): Promise<EmailAccountList> {
    return this.getEmailAccountBySmartleadClientId(
      smartleadClientId,
      pagination,
    );
  }

  /** Deletes an email account. */
  async deleteEmailAccount(
    emailAccount: EmailAccountReference,
  ): Promise<{ message: string; [key: string]: any }> {
    const smartleadInboxId = EmailinfraService.readInboxId(emailAccount);
    if (!smartleadInboxId) {
      throw new BadRequestException('smartleadInboxId is required');
    }
    // Make sure the account exists so callers get a not found error rather than
    // a silent no-op.
    await this.emailInfraEntity.read(smartleadInboxId);
    const res = await this.emailInfraEntity.delete(smartleadInboxId);
    return { ...res, smartleadInboxId };
  }

  /**
   * Imports the inboxes of a Smartlead client into the email account datastore.
   * Used by the import script, existing accounts keep their tags and campaign
   * associations.
   */
  async importEmailAccountsFromSmartlead({
    smartleadClientId,
    tags,
  }: {
    smartleadClientId?: string;
    tags?: string[];
  } = {}): Promise<EmailAccountList> {
    const inboxes = await this.emailInfraEntity.fetchRemoteInboxes({
      smartleadClientId,
    });
    this.logger.log(`Importing ${inboxes.length} inboxes from Smartlead`);
    const emailAccounts: EmailAccount[] = [];
    for (const inbox of inboxes) {
      try {
        emailAccounts.push(
          await this.saveFromRemoteInbox(inbox, tags ? { tags } : {}),
        );
      } catch (error) {
        this.logger.error(`Error importing inbox ${inbox?.id}: ${error}`);
      }
    }
    return toEmailAccountList(emailAccounts, {
      message: 'Email accounts imported successfully',
      numberOfEmailAccountsImported: emailAccounts.length,
      smartleadClientId,
    });
  }

  /**
   * Refreshes the warm up reputation of every stored email account. Used by the
   * reputation sync script.
   */
  async syncEmailAccountReputations(): Promise<EmailAccountList> {
    const emailAccounts = await this.emailInfraEntity.readAll();
    const inboxes = await this.emailInfraEntity.fetchRemoteInboxes();
    const inboxesById = new Map<string, any>(
      inboxes.map((inbox) => [`${inbox?.id}`, inbox]),
    );
    const syncedEmailAccounts: EmailAccount[] = [];
    for (const emailAccount of emailAccounts ? emailAccounts : []) {
      const inbox = inboxesById.get(`${emailAccount?.smartleadInboxId}`);
      if (!inbox) {
        this.logger.warn(
          `Inbox ${emailAccount?.smartleadInboxId} no longer exists in Smartlead`,
        );
        continue;
      }
      try {
        syncedEmailAccounts.push(await this.saveFromRemoteInbox(inbox));
      } catch (error) {
        this.logger.error(
          `Error syncing inbox ${emailAccount?.smartleadInboxId}: ${error}`,
        );
      }
    }
    return toEmailAccountList(syncedEmailAccounts, {
      message: 'Email account reputations synced successfully',
      numberOfEmailAccountsSynced: syncedEmailAccounts.length,
    });
  }

  /** Alias of {@link syncEmailAccountReputations}. */
  async syncDeliverabilityScores(): Promise<EmailAccountList> {
    return this.syncEmailAccountReputations();
  }

  /** Fetches an inbox straight from Smartlead. */
  async getSmartleadInbox(smartleadInboxId: string): Promise<any> {
    return this.emailInfraEntity.fetchRemoteInbox(smartleadInboxId);
  }

  /** Fetches the inboxes of a Smartlead client straight from Smartlead. */
  async getSmartleadInboxes(smartleadClientId?: string): Promise<any[]> {
    return this.emailInfraEntity.fetchRemoteInboxes({ smartleadClientId });
  }

  /**
   * Merges a Smartlead inbox with what we already store (and with the caller
   * provided fields) and persists the result.
   */
  private async saveFromRemoteInbox(
    inbox: any,
    input: EmailAccountInput = {},
  ): Promise<EmailAccount> {
    const smartleadInboxId = EmailinfraService.readInboxId(input)
      ? EmailinfraService.readInboxId(input)
      : `${inbox?.id}`;
    const existingEmailAccount =
      await this.emailInfraEntity.find(smartleadInboxId);
    const email = EmailinfraService.firstDefined(
      input?.email,
      existingEmailAccount?.email,
      inbox?.from_email,
      inbox?.email,
    );
    const emailAccount = new EmailAccount({
      ...(existingEmailAccount ? { ...existingEmailAccount } : {}),
      ...input,
      smartleadInboxId,
      email,
      domain: EmailAccount.deriveDomain(email),
      smartleadClientId: EmailinfraService.firstDefined(
        input?.smartleadClientId,
        existingEmailAccount?.smartleadClientId,
        inbox?.client_id,
      ),
      tags: [
        ...(existingEmailAccount?.tags ? existingEmailAccount.tags : []),
        ...(Array.isArray(input?.tags) ? input.tags : []),
      ],
      campaignIds: [
        ...(existingEmailAccount?.campaignIds
          ? existingEmailAccount.campaignIds
          : []),
        ...(Array.isArray(input?.campaignIds) ? input.campaignIds : []),
      ],
      // Creation time and warm up reputation always come from Smartlead.
      createdAt: EmailinfraService.firstDefined(
        inbox?.created_at,
        existingEmailAccount?.createdAt,
        input?.createdAt,
      ),
      deliverabilityScore: EmailinfraService.firstDefined(
        EmailAccount.readWarmupReputation(inbox),
        input?.deliverabilityScore,
        existingEmailAccount?.deliverabilityScore,
      ),
    });
    return this.emailInfraEntity.create(emailAccount);
  }

  private static readInboxId(
    emailAccount?: EmailAccountReference,
  ): string | undefined {
    if (emailAccount === null || emailAccount === undefined) {
      return undefined;
    }
    if (typeof emailAccount === 'string' || typeof emailAccount === 'number') {
      return `${emailAccount}`;
    }
    const id = EmailinfraService.firstDefined(
      emailAccount?.smartleadInboxId,
      emailAccount?.emailAccountId,
      emailAccount?.inboxId,
      emailAccount?.id,
    );
    return id === undefined || id === '' ? undefined : `${id}`;
  }

  private static readPagination(
    pagination?: { page?: number; pageSize?: number } | number,
    maybePageSize?: number,
  ): { page: number; pageSize: number } {
    const page =
      typeof pagination === 'number' ? pagination : pagination?.page;
    const pageSize =
      typeof pagination === 'number' ? maybePageSize : pagination?.pageSize;
    return {
      page: Number(page) > 0 ? Number(page) : 0,
      pageSize:
        Number(pageSize) > 0 ? Number(pageSize) : DEFAULT_EMAIL_ACCOUNT_PAGE_SIZE,
    };
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private static firstDefined(...values: any[]): any {
    return values.find((value) => value !== undefined && value !== null);
  }
}

import {
  Body,
  Controller,
  Delete,
  Get,
  Param,
  Post,
  Query,
  UseGuards,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { EmailinfraService } from './emailinfra.service';
import {
  AssociateEmailAccountsDto,
  EmailAccountDto,
  EmailAccountListDto,
} from './dto/emailAccount.dto';

@Controller('emailinfra')
export class EmailinfraController {
  constructor(private readonly emailinfraService: EmailinfraService) {}

  /** Creates (or refreshes) an email account from a Smartlead inbox. */
  @Post('email-account')
  @UseGuards(AuthGuard('user-api-key'))
  async saveEmailAccount(@Body() emailAccount: EmailAccountDto) {
    return this.emailinfraService.saveEmailAccount(emailAccount);
  }

  /** Imports every inbox of a Smartlead client. */
  @Post('email-account/import')
  @UseGuards(AuthGuard('user-api-key'))
  async importEmailAccounts(
    @Body() { smartleadClientId, tags }: { smartleadClientId?: string; tags?: string[] },
  ) {
    return this.emailinfraService.importEmailAccountsFromSmartlead({
      smartleadClientId,
      tags,
    });
  }

  /** Refreshes the warm up reputation of every stored email account. */
  @Post('email-account/sync-reputation')
  @UseGuards(AuthGuard('user-api-key'))
  async syncEmailAccountReputations() {
    return this.emailinfraService.syncEmailAccountReputations();
  }

  /** Associates inboxes with a campaign. */
  @Post('email-account/associate')
  @UseGuards(AuthGuard('user-api-key'))
  async associateEmailAccountsWithCampaign(
    @Body() { emailAccountIds, campaignId }: AssociateEmailAccountsDto,
  ) {
    return this.emailinfraService.associateEmailAccountsWithCampaign({
      emailAccountIds,
      campaignId,
    });
  }

  /** Returns the best inboxes to use for a campaign. */
  @Post('email-account/best')
  @UseGuards(AuthGuard('user-api-key'))
  async getBestEmailAccountsForCampaign(
    @Body() emailAccountList: EmailAccountListDto,
  ) {
    return this.emailinfraService.getBestEmailAccountsForCampaign(
      emailAccountList,
    );
  }

  /** Lists email accounts. */
  @Get('email-account')
  @UseGuards(AuthGuard('user-api-key'))
  async getAllEmailAccounts(
    @Query('page') page: number,
    @Query('pageSize') pageSize: number,
  ) {
    return this.emailinfraService.getAllEmailAccounts({ page, pageSize });
  }

  /** Reads an email account by email address. */
  @Get('email-account/email/:email')
  @UseGuards(AuthGuard('user-api-key'))
  async getEmailAccountByEmail(@Param('email') email: string) {
    return this.emailinfraService.getEmailAccountByEmail(email);
  }

  /** Reads every email account of a Smartlead client. */
  @Get('email-account/client/:smartleadClientId')
  @UseGuards(AuthGuard('user-api-key'))
  async getEmailAccountBySmartleadClientId(
    @Param('smartleadClientId') smartleadClientId: string,
  ) {
    return this.emailinfraService.getEmailAccountBySmartleadClientId(
      smartleadClientId,
    );
  }

  /** Reads an email account by Smartlead inbox id. */
  @Get('email-account/:smartleadInboxId')
  @UseGuards(AuthGuard('user-api-key'))
  async getEmailAccount(@Param('smartleadInboxId') smartleadInboxId: string) {
    return this.emailinfraService.getEmailAccount(smartleadInboxId);
  }

  /** Deletes an email account. */
  @Delete('email-account/:smartleadInboxId')
  @UseGuards(AuthGuard('user-api-key'))
  async deleteEmailAccount(
    @Param('smartleadInboxId') smartleadInboxId: string,
  ) {
    return this.emailinfraService.deleteEmailAccount(smartleadInboxId);
  }
}

