import { Module } from '@nestjs/common';
import { EmailinfraService } from './emailinfra.service';
import { EmailinfraController } from './emailinfra.controller';
import { DatastoreModule } from '../datastore/datastore.module';
import { EmailInfraEntity } from './entities/emailinfra.entity';

@Module({
  controllers: [EmailinfraController],
  providers: [EmailinfraService, EmailInfraEntity],
  imports: [DatastoreModule],
  exports: [EmailinfraService],
})
export class EmailinfraModule {}

/*
  Imports the warmed up Smartlead inboxes of a client into the email account
  datastore. Every inbox is keyed by its Smartlead inbox id, existing accounts
  keep their tags and campaign associations while the creation time and the warm
  up reputation are refreshed from Smartlead.

  Usage:
    SMARTLEAD_CLIENT_ID=22 node client/tools/importEmailAccounts.js
*/
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const BASE_URL = process.env.BASE_URL
  ? process.env.BASE_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;
const smartleadClientId = process.env.SMARTLEAD_CLIENT_ID;
const tags = process.env.TAGS ? process.env.TAGS.split(',') : undefined;

async function importEmailAccounts() {
  const url = `${BASE_URL}/emailinfra/email-account/import`;
  console.log('URL:', url);
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
    body: JSON.stringify({ smartleadClientId, tags }),
  });
  if (!res.ok) {
    console.error('Failed to import email accounts:', res.status);
    console.error(await res.text());
    process.exit(1);
  }
  const emailAccounts = await res.json();
  console.log(`Imported ${emailAccounts.length} email accounts`);
  emailAccounts.forEach((emailAccount) => {
    console.log(
      `${emailAccount.smartleadInboxId} ${emailAccount.email} ${emailAccount.deliverabilityScore}`,
    );
  });
}

importEmailAccounts().catch((error) => {
  console.error('Error importing email accounts:', error);
  process.exit(1);
});

/*
  Refreshes the Smartlead warm up reputation (the deliverability score) of every
  stored email account. Run it on a schedule so inbox selection always ranks on
  fresh reputations.

  Usage:
    node client/tools/syncEmailAccountReputation.js
*/
//eslint-disable-next-line
const { fetch } = require('cross-fetch');

const BASE_URL = process.env.BASE_URL
  ? process.env.BASE_URL
  : 'https://internal.prod.tenex.email';
const API_KEY = process.env.API_KEY;

async function syncEmailAccountReputation() {
  const url = `${BASE_URL}/emailinfra/email-account/sync-reputation`;
  console.log('URL:', url);
  const res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-API-KEY': API_KEY,
    },
  });
  if (!res.ok) {
    console.error('Failed to sync email account reputations:', res.status);
    console.error(await res.text());
    process.exit(1);
  }
  const emailAccounts = await res.json();
  console.log(`Synced ${emailAccounts.length} email accounts`);
  emailAccounts.forEach((emailAccount) => {
    console.log(
      `${emailAccount.smartleadInboxId} ${emailAccount.email} ${emailAccount.deliverabilityScore}`,
    );
  });
}

syncEmailAccountReputation().catch((error) => {
  console.error('Error syncing email account reputations:', error);
  process.exit(1);
});

import { EmailAccount } from './emailAccount.entity';
import {
  DeliverabilityScore,
  mapDeliverabilityScore,
} from '../dto/deliverabilityScore.dto';

describe('EmailAccount', () => {
  it('derives the domain from the email address', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: '1',
      email: 'sales@warmdomain.com',
      smartleadClientId: '22',
    });
    expect(emailAccount.domain).toBe('warmdomain.com');
  });

  it('keeps the smartlead inbox id and client id as strings', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: 1234,
      smartleadClientId: 22,
      email: 'sales@warmdomain.com',
    });
    expect(emailAccount.smartleadInboxId).toBe('1234');
    expect(emailAccount.smartleadClientId).toBe('22');
  });

  it('exposes the number of associated campaigns', () => {
    const emailAccount = new EmailAccount({
      smartleadInboxId: '1',
      email: 'sales@warmdomain.com',
      campaignIds: ['campaign-1', 'campaign-2'],
    });
    expect(emailAccount.numberOfCampaignAssociated).toBe(2);
    expect(new EmailAccount({ smartleadInboxId: '2' })
      .numberOfCampaignAssociated).toBe(0);
  });

  it('only associates a campaign once', () => {
    const emailAccount = new EmailAccount({ smartleadInboxId: '1' });
    expect(emailAccount.associateCampaign('campaign-1')).toBe(true);
    expect(emailAccount.associateCampaign('campaign-1')).toBe(false);
    expect(emailAccount.campaignIds).toEqual(['campaign-1']);
    expect(emailAccount.numberOfCampaignAssociated).toBe(1);
  });

  it('keeps the warm up reputation as the deliverability score', () => {
    const emailAccount = EmailAccount.fromSmartleadInbox({
      id: 1,
      from_email: 'sales@warmdomain.com',
      client_id: 22,
      created_at: '2024-01-01T00:00:00.000Z',
      warmup_details: { warmup_reputation: '98%' },
    });
    expect(emailAccount.deliverabilityScore).toBe(98);
    expect(emailAccount.createdAt).toBe('2024-01-01T00:00:00.000Z');
    expect(emailAccount.email).toBe('sales@warmdomain.com');
    expect(emailAccount.smartleadClientId).toBe('22');
  });

  it('maps the deliverability score onto its band', () => {
    const bandFor = (deliverabilityScore?: number) =>
      new EmailAccount({ smartleadInboxId: '1', deliverabilityScore })
        .deliverabilityBand;
    expect(bandFor(100)).toBe(DeliverabilityScore.HIGH);
    expect(bandFor(99)).toBe(DeliverabilityScore.MEDIUM);
    expect(bandFor(98)).toBe(DeliverabilityScore.MEDIUM);
    expect(bandFor(97)).toBe(DeliverabilityScore.LOW);
    expect(bandFor(95)).toBe(DeliverabilityScore.LOW);
    expect(bandFor(94)).toBe(DeliverabilityScore.BURNED);
    expect(bandFor(0)).toBe(DeliverabilityScore.BURNED);
    expect(bandFor(undefined)).toBe(DeliverabilityScore.UNKNOWN);
    expect(mapDeliverabilityScore(null)).toBe(DeliverabilityScore.UNKNOWN);
  });

  it('drops datastore internals when mapping documents', () => {
    const emailAccount = EmailAccount.map({
      data: {
        smartleadInboxId: '1',
        email: 'sales@warmdomain.com',
        _collection: 'EMAIL_ACCOUNT',
        _id: 'mongo-id',
      },
    });
    expect(emailAccount.smartleadInboxId).toBe('1');
    expect(emailAccount._collection).toBeUndefined();
    expect(emailAccount._id).toBeUndefined();
  });
});

import { NotFoundException } from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { EmailinfraService } from './emailinfra.service';
import { DatastoreService } from '../datastore/datastore.service';
import { documentType } from '../datastore/entites/documentType';
import { EmailInfraEntity } from './entities/emailinfra.entity';
import { EmailAccount } from './entities/emailAccount.entity';
import { DeliverabilityScore } from './dto/deliverabilityScore.dto';

/**
 * Minimal in memory stand in for the datastore, it behaves like the mongo
 * datastore for the queries the email account subsystem makes.
 */
class InMemoryDatastore {
  documents = new Map<string, any>();
  store = jest.fn(async ({ data, context }: any) => {
    this.documents.set(context.uniqueId, { data });
    return { message: 'Data stored successfully', uniqueId: context.uniqueId };
  });
  getByField = jest.fn(
    async ({ fieldKey, fieldValue, documentType: type, pagination }: any) => {
      expect(type).toBe(documentType.EMAIL_ACCOUNT);
      const field = fieldKey.replace('data.', '');
      let values = [...this.documents.values()].map(({ data }) => data);
      values = values.filter((value) =>
        fieldValue && typeof fieldValue === 'object'
          ? value[field] !== undefined
          : `${value[field]}` === `${fieldValue}`,
      );
      if (pagination) {
        const start = pagination.page * pagination.pageSize;
        values = values.slice(start, start + pagination.pageSize);
      }
      return { data: values.length ? values : undefined };
    },
  );
  remove = jest.fn(async ({ id }: any) => {
    this.documents.delete(id);
    return { message: 'Data removed successfully' };
  });
  getPageCount = jest.fn(async () => this.documents.size);
}

const remoteInbox = ({
  id,
  email,
  clientId = 22,
  warmupReputation,
  createdAt = '2024-01-01T00:00:00.000Z',
}: {
  id: number | string;
  email: string;
  clientId?: number | string;
  warmupReputation?: number;
  createdAt?: string;
}) => ({
  id,
  from_name: 'Sales',
  from_email: email,
  client_id: clientId,
  created_at: createdAt,
  warmup_details: { warmup_reputation: warmupReputation },
});

describe('EmailinfraService', () => {
  it('should be defined', async () => {
    const module: TestingModule = await Test.createTestingModule({
      providers: [EmailinfraService],
    }).compile();

    expect(module.get<EmailinfraService>(EmailinfraService)).toBeDefined();
  });

  describe('with a datastore', () => {
    let service: EmailinfraService;
    let datastore: InMemoryDatastore;
    let inboxes: any[];

    const seedEmailAccount = async (
      emailAccount: Partial<EmailAccount> & { smartleadInboxId: string },
    ) => {
      datastore.documents.set(emailAccount.smartleadInboxId, {
        data: { ...new EmailAccount(emailAccount) },
      });
    };

    beforeEach(async () => {
      datastore = new InMemoryDatastore();
      inboxes = [];
      const module: TestingModule = await Test.createTestingModule({
        providers: [
          EmailinfraService,
          EmailInfraEntity,
          { provide: DatastoreService, useValue: datastore },
        ],
      }).compile();
      service = module.get<EmailinfraService>(EmailinfraService);
      global.fetch = jest.fn(async (url: string) => {
        if (`${url}`.includes('email-accounts/?')) {
          return { ok: true, status: 200, json: async () => inboxes } as any;
        }
        const id = `${url}`.split('email-accounts/')[1].split('/')[0];
        const inbox = inboxes.find((i) => `${i.id}` === id);
        if (!inbox) {
          return { ok: false, status: 404, json: async () => ({}) } as any;
        }
        return { ok: true, status: 200, json: async () => inbox } as any;
      }) as any;
    });

    describe('saveEmailAccount', () => {
      it('hydrates the creation time and the warm up reputation from smartlead', async () => {
        inboxes = [
          remoteInbox({
            id: 1,
            email: 'sales@warmdomain.com',
            warmupReputation: 99,
            createdAt: '2023-05-05T00:00:00.000Z',
          }),
        ];
        const emailAccount = await service.saveEmailAccount({
          smartleadInboxId: '1',
          email: 'sales@warmdomain.com',
          smartleadClientId: '22',
          tags: ['primary'],
        });
        expect(emailAccount.smartleadInboxId).toBe('1');
        expect(emailAccount.email).toBe('sales@warmdomain.com');
        expect(emailAccount.smartleadClientId).toBe('22');
        expect(emailAccount.domain).toBe('warmdomain.com');
        expect(emailAccount.tags).toEqual(['primary']);
        expect(emailAccount.campaignIds).toEqual([]);
        expect(emailAccount.createdAt).toBe('2023-05-05T00:00:00.000Z');
        expect(emailAccount.deliverabilityScore).toBe(99);
        expect(emailAccount.deliverabilityBand).toBe(
          DeliverabilityScore.MEDIUM,
        );
        expect(datastore.store).toHaveBeenCalledWith(
          expect.objectContaining({
            context: {
              uniqueId: '1',
              documentType: documentType.EMAIL_ACCOUNT,
            },
          }),
        );
      });

      it('rejects an inbox which does not exist in smartlead', async () => {
        await expect(
          service.saveEmailAccount({
            smartleadInboxId: '404',
            email: 'sales@warmdomain.com',
            smartleadClientId: '22',
          }),
        ).rejects.toThrow(NotFoundException);
        expect(datastore.store).not.toHaveBeenCalled();
      });

      it('keeps the existing campaign associations when refreshed', async () => {
        await seedEmailAccount({
          smartleadInboxId: '1',
          email: 'sales@warmdomain.com',
          smartleadClientId: '22',
          campaignIds: ['campaign-1'],
          tags: ['primary'],
        });
        inboxes = [
          remoteInbox({
            id: 1,
            email: 'sales@warmdomain.com',
            warmupReputation: 100,
          }),
        ];
        const emailAccount = await service.saveEmailAccount({
          smartleadInboxId: '1',
        });
        expect(emailAccount.campaignIds).toEqual(['campaign-1']);
        expect(emailAccount.tags).toEqual(['primary']);
        expect(emailAccount.deliverabilityScore).toBe(100);
        expect(emailAccount.deliverabilityBand).toBe(DeliverabilityScore.HIGH);
      });
    });

    describe('lookups', () => {
      beforeEach(async () => {
        await seedEmailAccount({
          smartleadInboxId: '1',
          email: 'one@warmdomain.com',
          smartleadClientId: '22',
        });
        await seedEmailAccount({
          smartleadInboxId: '2',
          email: 'two@warmdomain.com',
          smartleadClientId: '22',
        });
        await seedEmailAccount({
          smartleadInboxId: '3',
          email: 'three@otherdomain.com',
          smartleadClientId: '33',
        });
      });

      it('reads an email account by inbox id', async () => {
        const emailAccount = await service.getEmailAccount('2');
        expect(emailAccount.email).toBe('two@warmdomain.com');
        expect(await service.getEmailAccountById('1')).toBeInstanceOf(
          EmailAccount,
        );
      });

      it('reads an email account by email', async () => {
        const emailAccount = await service.getEmailAccountByEmail(
          'three@otherdomain.com',
        );
        expect(emailAccount.smartleadInboxId).toBe('3');
      });

      it('reads the email accounts of a smartlead client', async () => {
        const emailAccounts =
          await service.getEmailAccountBySmartleadClientId('22');
        expect(emailAccounts.map((e) => e.smartleadInboxId)).toEqual([
          '1',
          '2',
        ]);
      });

      it('throws when the email account does not exist', async () => {
        await expect(service.getEmailAccount('404')).rejects.toThrow(
          NotFoundException,
        );
        await expect(
          service.getEmailAccountByEmail('nobody@warmdomain.com'),
        ).rejects.toThrow(NotFoundException);
      });

      it('lists email accounts by page', async () => {
        const firstPage = await service.getAllEmailAccounts({
          page: 0,
          pageSize: 2,
        });
        expect(firstPage.map((e) => e.smartleadInboxId)).toEqual(['1', '2']);
        expect(firstPage.pageCount).toBe(2);
        expect(firstPage.total).toBe(3);
        const secondPage = await service.getAllEmailAccounts({
          page: 1,
          pageSize: 2,
        });
        expect(secondPage.map((e) => e.smartleadInboxId)).toEqual(['3']);
      });

      it('deletes an email account', async () => {
        await service.deleteEmailAccount('1');
        expect(datastore.remove).toHaveBeenCalledWith({
          id: '1',
          documentType: documentType.EMAIL_ACCOUNT,
        });
        await expect(service.getEmailAccount('1')).rejects.toThrow(
          NotFoundException,
        );
      });
    });

    describe('associateEmailAccountsWithCampaign', () => {
      beforeEach(async () => {
        await seedEmailAccount({
          smartleadInboxId: '1',
          email: 'one@warmdomain.com',
          smartleadClientId: '22',
        });
        await seedEmailAccount({
          smartleadInboxId: '2',
          email: 'two@warmdomain.com',
          smartleadClientId: '22',
          campaignIds: ['campaign-1'],
        });
      });

      it('treats repeated inbox ids as a single inbox', async () => {
        const emailAccounts =
          await service.associateEmailAccountsWithCampaign({
            emailAccountIds: ['1', '1'],
            campaignId: 'campaign-2',
          });
        expect(emailAccounts.length).toBe(1);
        expect(emailAccounts[0].campaignIds).toEqual(['campaign-2']);
        expect(datastore.store).toHaveBeenCalledTimes(1);
      });

      it('is idempotent', async () => {
        await service.associateEmailAccountsWithCampaign({
          emailAccountIds: ['2'],
          campaignId: 'campaign-1',
        });
        const emailAccount = await service.getEmailAccount('2');
        expect(emailAccount.campaignIds).toEqual(['campaign-1']);
        expect(emailAccount.numberOfCampaignAssociated).toBe(1);
        expect(datastore.store).not.toHaveBeenCalled();
      });

      it('rejects the whole request when an inbox is missing', async () => {
        await expect(
          service.associateEmailAccountsWithCampaign({
            emailAccountIds: ['1', '404'],
            campaignId: 'campaign-2',
          }),
        ).rejects.toThrow(NotFoundException);
        expect(datastore.store).not.toHaveBeenCalled();
        const emailAccount = await service.getEmailAccount('1');
        expect(emailAccount.campaignIds).toEqual([]);
      });
    });

    describe('getBestEmailAccountsForCampaign', () => {
      it('sizes the pool from the campaign volume', () => {
        expect(
          service.getRequiredNumberOfInboxes({
            totalNumberOfEmailsToSend: 500,
            numberOfDaysInCampaign: 10,
            numberOfEmailsPerInboxPerDay: 20,
          }),
        ).toBe(2);
        // 10 days at 20 emails per inbox per day are the defaults.
        expect(
          service.getRequiredNumberOfInboxes({
            totalNumberOfEmailsToSend: 600,
          }),
        ).toBe(3);
      });

      it('ranks by score, campaigns, domain spread and creation time', async () => {
        await seedEmailAccount({
          smartleadInboxId: 'low-score',
          email: 'a@one.com',
          smartleadClientId: '22',
          deliverabilityScore: 95,
        });
        await seedEmailAccount({
          smartleadInboxId: 'best',
          email: 'b@two.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
          createdAt: '2020-01-01T00:00:00.000Z',
        });
        await seedEmailAccount({
          smartleadInboxId: 'busy',
          email: 'c@three.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
          campaignIds: ['campaign-1'],
          createdAt: '2019-01-01T00:00:00.000Z',
        });
        await seedEmailAccount({
          smartleadInboxId: 'shared-domain',
          email: 'd@four.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
          createdAt: '2019-01-01T00:00:00.000Z',
        });
        await seedEmailAccount({
          smartleadInboxId: 'shared-domain-sibling',
          email: 'e@four.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
          createdAt: '2021-01-01T00:00:00.000Z',
        });
        await seedEmailAccount({
          smartleadInboxId: 'other-client',
          email: 'f@five.com',
          smartleadClientId: '33',
          deliverabilityScore: 100,
        });

        const emailAccounts = await service.getBestEmailAccountsForCampaign({
          smartleadClientId: '22',
          campaignId: 'campaign-2',
          totalNumberOfEmailsToSend: 2000,
          numberOfDaysInCampaign: 10,
          numberOfEmailsPerInboxPerDay: 20,
        });
        expect(emailAccounts.requiredNumberOfInboxes).toBe(10);
        expect(emailAccounts.map((e) => e.smartleadInboxId)).toEqual([
          // 100, no campaigns, only inbox on its domain, oldest of the two
          'best',
          // 100, no campaigns, shares its domain, oldest first
          'shared-domain',
          'shared-domain-sibling',
          // 100 but already used by a campaign
          'busy',
          // lowest score last
          'low-score',
        ]);
      });

      it('only returns as many inboxes as the campaign needs', async () => {
        await seedEmailAccount({
          smartleadInboxId: '1',
          email: 'a@one.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
        });
        await seedEmailAccount({
          smartleadInboxId: '2',
          email: 'b@two.com',
          smartleadClientId: '22',
          deliverabilityScore: 98,
        });
        const emailAccounts = await service.getBestEmailAccountsForCampaign({
          smartleadClientId: '22',
          campaignId: 'campaign-1',
          totalNumberOfEmailsToSend: 200,
        });
        expect(emailAccounts.map((e) => e.smartleadInboxId)).toEqual(['1']);
      });
    });

    describe('smartlead synchronisation', () => {
      it('imports the inboxes of a smartlead client', async () => {
        inboxes = [
          remoteInbox({
            id: 1,
            email: 'one@warmdomain.com',
            warmupReputation: 100,
          }),
          remoteInbox({
            id: 2,
            email: 'two@warmdomain.com',
            clientId: 33,
            warmupReputation: 90,
          }),
        ];
        const emailAccounts = await service.importEmailAccountsFromSmartlead({
          smartleadClientId: '22',
        });
        expect(emailAccounts.map((e) => e.smartleadInboxId)).toEqual(['1']);
        expect(emailAccounts[0].deliverabilityScore).toBe(100);
        expect(emailAccounts[0].smartleadClientId).toBe('22');
      });

      it('refreshes the deliverability score of stored accounts', async () => {
        await seedEmailAccount({
          smartleadInboxId: '1',
          email: 'one@warmdomain.com',
          smartleadClientId: '22',
          deliverabilityScore: 100,
          campaignIds: ['campaign-1'],
        });
        inboxes = [
          remoteInbox({
            id: 1,
            email: 'one@warmdomain.com',
            warmupReputation: 80,
          }),
        ];
        const emailAccounts = await service.syncEmailAccountReputations();
        expect(emailAccounts[0].deliverabilityScore).toBe(80);
        expect(emailAccounts[0].deliverabilityBand).toBe(
          DeliverabilityScore.BURNED,
        );
        expect(emailAccounts[0].campaignIds).toEqual(['campaign-1']);
      });
    });
  });
});

